import unittest
from candidate import is_prime

class TestIsPrimeFunction(unittest.TestCase):
    def test_is_prime_number(self):
        self.assertTrue(is_prime(101))

    def test_is_prime_number_with_small_prime_factors(self):
        self.assertFalse(is_prime(6))

    def test_is_prime_number_with_large_prime_factors(self):
        self.assertTrue(is_prime(13441))

    def test_is_prime_small_prime_number(self):
        self.assertTrue(is_prime(11))

    def test_is_prime_small_non_prime_number(self):
        self.assertFalse(is_prime(4))

    def test_is_prime_number_at_boundary(self):
        self.assertFalse(is_prime(1))

    def test_is_prime_number_with_negative_input(self):
        with self.assertRaises(TypeError):
            is_prime(-10)

    def test_is_prime_number_with_non_integer_input(self):
        with self.assertRaises(TypeError):
            is_prime(10.5)

    def test_is_prime_number_with_none_input(self):
        with self.assertRaises(TypeError):
            is_prime(None)

    def test_is_prime_number_with_zero_input(self):
        self.assertFalse(is_prime(0))

    def test_is_prime_number_with_one_input(self):
        self.assertFalse(is_prime(1))

if __name__ == '__main__':
    unittest.main()
